class Solution {
    fun countOperationsToEmptyArray(nums:IntArray):Long{
        val n=nums.size;
        val tree=IntArray(n+1);
        fun add(indexInput:Int,delta:Int){
            var index=indexInput+1;
            while(index<=n){
                tree[index]+=delta;
                index+=index and -index
            }
        };
        fun sum(indexInput:Int):Int{
            var index=indexInput+1;
            var result=0;
            while(index>0){
                result+=tree[index];
                index-=index and -index
            };
            return result
        };
        fun range(left:Int,right:Int):Int{
            return if(left>right)0 else sum(right)-(if(left==0)0 else sum(left-1))
        };
        for(i in nums.indices)add(i,1);
        val order=nums.indices.sortedBy{
            nums[it]
        };
        var answer=0L;
        var current=0;
        for(target in order){
            answer+=(if(target>=current)range(current,target) else range(current,n-1)+range(0,target));
            add(target,-1);
            current=(target+1)%n
        };
        return answer
    }
}

